sys_script_client.script:
function onSubmit() {
    //Type appropriate comment here, and begin script below

	// Created By : Shivam Dighe
	// Created on : 21/07/2026
	// Purpose : If the asset type is hardware and the estimated cost field is empty , then stop the form submission and show an error message

    var cost = g_form.getValue('estimated_cost');
    var assetType = g_form.getValue('asset_type');
    if (cost.endsWith(";0.00") && assetType != "software") {
		g_form.addErrorMessage("Asset type is hardware , please fill the estimated cost field");
        return false;
    }

}
